import React, { useState, useEffect } from "react";
import { Bar } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from "chart.js";
import { watchlist as initialList } from "../data/watchlist"; // your static list

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

const LiveWatchlist = () => {
  const [stocks, setStocks] = useState(initialList);

  useEffect(() => {
    const interval = setInterval(() => {
      setStocks((prevStocks) =>
        prevStocks.map((stock) => {
          // Random ±2% change
          const changePercent = (Math.random() * 4 - 2).toFixed(2);
          const newPrice = stock.price + (stock.price * changePercent) / 100;

          return {
            ...stock,
            price: parseFloat(newPrice.toFixed(2)),
            percent:
              (changePercent > 0 ? "+" : "") + changePercent + "%",
            isDown: changePercent < 0,
          };
        })
      );
    }, 1000);

    return () => clearInterval(interval);
  }, []);

  const labels = stocks.map((stock) => stock.name);

  const data = {
    labels,
    datasets: [
      {
        label: "Live Stock Prices (₹)",
        data: stocks.map((stock) => stock.price),
        backgroundColor: [
          "rgba(255, 99, 132, 0.5)",
          "rgba(54, 162, 235, 0.5)",
          "rgba(255, 206, 86, 0.5)",
          "rgba(75, 192, 192, 0.5)",
          "rgba(153, 102, 255, 0.5)",
          "rgba(255, 159, 64, 0.5)",
          "rgba(199, 99, 255, 0.5)",
          "rgba(255, 120, 170, 0.5)",
          "rgba(140, 200, 255, 0.5)",
        ],
        borderColor: [
          "rgba(255, 99, 132, 1)",
          "rgba(54, 162, 235, 1)",
          "rgba(255, 206, 86, 1)",
          "rgba(75, 192, 192, 1)",
          "rgba(153, 102, 255, 1)",
          "rgba(255, 159, 64, 1)",
        ],
        borderWidth: 1,
      },
    ],
  };

  const options = {
    responsive: true,
    plugins: {
      legend: { display: false },
      title: {
        display: true,
        text: "Live Stock Prices (updated every second)",
        font: { size: 18 },
      },
    },
    scales: {
      y: {
        beginAtZero: false,
        ticks: { color: "#333" },
      },
      x: {
        ticks: { color: "#333" },
      },
    },
  };

  return (
    <div className="watchlist-container">
      <h2>📊 Live Watchlist</h2>

      <div className="chart-container">
        <Bar data={data} options={options} />
      </div>

      <table className="stock-table">
        <thead>
          <tr>
            <th>Stock</th>
            <th>Price (₹)</th>
            <th>Change (%)</th>
          </tr>
        </thead>
        <tbody>
          {stocks.map((stock, index) => (
            <tr key={index} style={{ color: stock.isDown ? "red" : "green" }}>
              <td>{stock.name}</td>
              <td>{stock.price.toFixed(2)}</td>
              <td>{stock.percent}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default LiveWatchlist;
